        var invB = -b / det;
        var invC = -c / det;
        var invD = a / det;
        var deltaX = invA * dx + invB * dy;
        var deltaY = invC * dx + invD * dy;
        guess[0] += deltaX;
        guess[1] += deltaY;
    }
    return guess;
}

